import { Type } from '@angular/core';

/* ---- Generated by tools/gen-docs.mjs ---- */

export interface DemoSource {
  file: string;
  code: string;
  html: string;
}

export interface ApiMember {
  name: string;
  kind: string;
  type: string;
  description: string;
  default?: string;
  required?: boolean;
}

export interface ApiClass {
  name: string;
  kind: string;
  selector?: string;
  description: string;
  members: ApiMember[];
}

export interface CssVarDoc {
  name: string;
  fallback: string;
}

export interface EntryData {
  api: { classes: ApiClass[]; cssVars: CssVarDoc[] };
  sources: Record<string, DemoSource>;
}

export interface TokenDoc {
  name: string;
  value: string;
  group: string;
  comment: string;
}

/* ---- Authored per component ---- */

export interface DemoDoc {
  /** Key in `EntryData.sources` (file name without `.demo.ts`). */
  source: string;
  title: string;
  description?: string;
  component: Type<unknown>;
  /** Render the preview on the plain canvas instead of the wallpaper stage. */
  plain?: boolean;
}

export interface KeyboardDoc {
  keys: string[];
  action: string;
}

export interface SlotDoc {
  name: string;
  description: string;
}

export interface ComponentDoc {
  slug: string;
  title: string;
  /** One or two sentences: what it is and when to use it. */
  description: string;
  /** Entry point name, e.g. `button` → `@kenny/ui/button`. */
  entry: string;
  data: EntryData;
  demos: DemoDoc[];
  playground?: Type<unknown>;
  /** Limit the API tables to these classes (defaults to all in the entry point). */
  apiClasses?: string[];
  slots?: SlotDoc[];
  keyboard?: KeyboardDoc[];
  a11y?: string[];
}
